// Effects catalogue of the advanced mode (Cinta's own implementations, drawn by src/motion-render/fx.ts).
// Every parameter is a Prop, so it can be keyframed or driven by an expression.
import { uid } from '../model';
import { P, type FxInstance, type Prop, type PVal } from './model';
import { n, pc, an, co, pt, bo, ly, CHANNELS, MATTE_CH, FIT, cu, tx, lv, hc, ch } from './fxparams';
import { FX_GROUPS } from './fx-groups';

export type ParamType = 'number' | 'percent' | 'angle' | 'color' | 'point' | 'bool' | 'choice' | 'layer' | 'curve' | 'text';
export interface ParamDef {
  id: string;
  name: string;
  type: ParamType;
  def: PVal;
  min?: number;
  max?: number;
  /** point defaults given as fractions of the layer size */
  rel?: boolean;
  choices?: { id: string; name: string }[];
}
export interface FxDef {
  id: string; name: string; cat: string; params: ParamDef[];
  /** values that make the effect visible on a still solid, for the catalogue test (when its defaults are neutral) */
  probe?: Record<string, PVal>;
  /** leaves a still layer unchanged even with probe (acts on time, needs a mask, EXR channels…) */
  still?: boolean;
}

