export const FX_CATS = [...new Set(FX.map((f) => f.cat))];

export function fxDef(id: string): FxDef {
  const d = FX.find((f) => f.id === id || f.name.toLowerCase() === id.toLowerCase());
  if (!d) throw new Error(`No existe el efecto «${id}». Use catalog_list con kind motion_effects.`);
  return d;
}

/** New effect instance with defaults (relative points resolved against the layer size). */
export function newFx(id: string, w: number, h: number, values: Record<string, PVal | boolean> = {}): FxInstance {
  const d = fxDef(id);
  const params: Record<string, Prop> = {};
  for (const p of d.params) {
    let v: PVal = p.def;
    if (p.type === 'point' && p.rel && Array.isArray(v)) v = [v[0] * w, v[1] * h];
    const given = values[p.id];
    if (given !== undefined) v = typeof given === 'boolean' ? (given ? 1 : 0) : given;
    params[p.id] = P(v);
  }
  const unknown = Object.keys(values).filter((k) => !d.params.some((p) => p.id === k));
  if (unknown.length) throw new Error(`«${d.name}» no tiene el parámetro ${unknown.join(', ')}. Tiene: ${d.params.map((p) => p.id).join(', ')}.`);
  return { id: uid('f'), fx: d.id, name: d.name, on: true, params };
}
